package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** MCAR pairwise-covariance RAM discrepancy fitting, with empirical case inference only. */
public final class PairwiseSem {
    private PairwiseSem(){}
    public record Fit(SemModel.Model model,CovarianceSem.Options criterionOptions,PairwiseMoments.Fit moments,int iterations,boolean converged,
                      String convergenceReason,boolean locallyIdentified,int informationRank,int covarianceRestrictions,double discrepancy,double standardizedResidual,
                      double[] estimates,double[][] impliedCovariance,double[][] directed,double[][] disturbanceCovariance,double[][] fullCovariance,double[][] standardizedDirected,List<String> warnings){
        public Fit{estimates=estimates.clone();impliedCovariance=Matrices.copy(impliedCovariance);directed=Matrices.copy(directed);disturbanceCovariance=Matrices.copy(disturbanceCovariance);fullCovariance=Matrices.copy(fullCovariance);standardizedDirected=Matrices.copy(standardizedDirected);warnings=List.copyOf(warnings);}
        @Override public double[] estimates(){return estimates.clone();}
        @Override public double[][] impliedCovariance(){return Matrices.copy(impliedCovariance);}
        @Override public double[][] directed(){return Matrices.copy(directed);}
        @Override public double[][] disturbanceCovariance(){return Matrices.copy(disturbanceCovariance);}
        @Override public double[][] fullCovariance(){return Matrices.copy(fullCovariance);}
        @Override public double[][] standardizedDirected(){return Matrices.copy(standardizedDirected);}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    public static Fit fit(double[][] raw,List<String> names,SemModel.Model model,CovarianceSem.Options options){if(options.meanStructure())throw new IllegalArgumentException("Pairwise RAM fitting is a covariance-only MCAR contract; mean-structure estimation requires another declared missing-data method.");if(model.parameters().stream().flatMap(p->p.locations().stream()).anyMatch(location->location.kind()==SemModel.Kind.INTERCEPT))throw new IllegalArgumentException("Remove free mean/intercept parameters for pairwise covariance-only fitting.");var moments=PairwiseMoments.fit(raw,names);if(names.size()!=model.observed().length||moments.sourceRows()<names.size()+3||!PairwiseMoments.covarianceAdmissible(moments.covariance()))throw new IllegalArgumentException("Pairwise RAM fitting requires matching observed order, sufficient original rows and a complete positive-definite sample covariance.");for(var row:moments.counts())for(int count:row)if(count<3)throw new IllegalArgumentException("Each covariance pair needs at least three observed cases.");var criterion=new CovarianceSem.Options(options.maxIterations(),options.gradientTolerance(),options.functionTolerance(),CovarianceSem.Likelihood.WISHART,false,options.confidence(),options.information());var point=CovarianceSem.fitCovariance(moments.covariance(),moments.means(),moments.sourceRows(),model,criterion);List<String>warnings=new ArrayList<>(moments.warnings());warnings.addAll(point.warnings());warnings.add("This minimizes a sample-covariance RAM discrepancy on pairwise moments under an MCAR interpretation. The Wishart setting denotes the point-criterion/sample-divisor convention, not a valid incomplete-data Wishart likelihood.");warnings.add("Different pairs have different effective sample sizes. Ordinary likelihood standard errors, chi-square P, likelihood-ratio tests, RMSEA intervals, likelihood information criteria and mean-structure estimates are not supplied. Use shared original-case bootstrap uncertainty for free RAM parameters.");warnings.add("Displayed covariance restriction count, discrepancy and standardized residual are descriptive. They do not establish fit-test calibration or causal identification.");return new Fit(model,criterion,moments,point.iterations(),point.converged(),point.convergenceReason(),point.identified(),point.informationRank(),point.degreesOfFreedom(),point.discrepancy(),point.srmr(),point.estimates(),point.impliedCovariance(),point.directed(),point.disturbanceCovariance(),point.fullCovariance(),point.standardizedDirected(),warnings);}
    public static Resampled bootstrap(double[][] raw,List<String> names,SemModel.Model model,CovarianceSem.Options settings,Bootstrap.Options options,IntConsumer progress){Fit point=fit(raw,names,model,settings);if(!point.converged||!point.locallyIdentified||improper(point))throw new IllegalArgumentException("Pairwise SEM inference requires a converged, locally identified, proper point solution.");var parameters=model.parameters().stream().map(p->new Bootstrap.Parameter("Pairwise RAM parameter",-1,-1,-1,p.name())).toList();var inference=Resampling.run(PairwiseMoments.pack(raw),parameters,point.estimates,options,(sample,rows)->{Fit fit=fit(PairwiseMoments.unpack(sample),names,model,settings);if(!fit.converged||!fit.locallyIdentified||improper(fit))throw new IllegalArgumentException("Pairwise SEM replicate is nonconverged, unidentified or improper.");return fit.estimates;},progress,"Pairwise-covariance RAM criterion","Every shared original case/jackknife draw retains its missingness mask, recomputes all pair-specific covariances and refits the constrained covariance model. Pairwise non-PD/sparse/improper fits fail without replacement; no artificial cases or original-sample pair moments are reused.");if(model.parameters().stream().anyMatch(p->p.lower()!=null||p.upper()!=null))inference=Resampling.suppressTests(inference,p->true,"Bounded RAM parameters do not have a regular ratio-test calibration; empirical intervals remain descriptive, not boundary-adjusted tests.");List<String>warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);return new Resampled(point,new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator()));}
    private static boolean improper(Fit fit){return fit.warnings.stream().anyMatch(w->w.contains("Heywood")||w.contains("not positive semidefinite"));}
}
